function brandIcon(label){
 const x=String(label).toLowerCase();
 const brand=(src,cls,alt)=>`<img class="brand-logo ${cls||''}" src="${src}" alt="${alt||''}" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'">`;
 if(x.includes('nmap')) return brand('assets/brands/nmap.svg','nmap','Nmap');
 if(x.includes('metasploit')) return brand('assets/brands/metasploit.svg','metasploit','Metasploit');
 if(x.includes('hydra')) return brand('assets/brands/hydra.svg','hydra','THC Hydra');
 if(x.includes('wireshark')) return brand('assets/brands/wireshark.svg','wireshark','Wireshark');
 if(x.includes('tryhackme')) return brand('assets/brands/tryhackme.svg','tryhackme','TryHackMe');
 if(x.includes('huawei')) return brand('assets/brands/huawei.svg','huawei','Huawei');
 if(x.includes('openwrt')) return brand('assets/brands/openwrt.svg','openwrt','OpenWrt');
 if(x.includes('antenna')||x.includes('أنتينا')) return `<svg class="brand-svg antenna" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 8v19M11 27h10M12 13c-3 2-4 5-4 8M20 13c3 2 4 5 4 8M8 9c-5 4-7 8-7 13M24 9c5 4 7 8 7 13"/></svg>`;
 if(x.includes('signal')||x.includes('الإشارة')) return `<svg class="brand-svg signal" viewBox="0 0 32 32" aria-hidden="true"><path d="M5 26v-5h4v5M12 26V16h4v10M19 26V11h4v15M26 26V6h3v20"/></svg>`;
 if(x.includes('باركود')||x.includes('barcode')) return `<svg class="brand-svg support" viewBox="0 0 32 32"><path d="M5 8h22v16H5zM9 11v10M12 11v10M16 11v10M21 11v10M24 11v10"/></svg>`;
 if(x.includes('نسخ احتياطي')||x.includes('backup')||x.includes('data protection')) return `<svg class="brand-svg support" viewBox="0 0 32 32"><path d="M16 4 26 8v7c0 6-4 10-10 13C10 25 6 21 6 15V8l10-4Z"/><path d="M11 16h10M16 11v10"/></svg>`;
 if(x.includes('أعطال')||x.includes('troubleshooting')) return `<svg class="brand-svg support" viewBox="0 0 32 32"><path d="m7 25 8-8M20 5a6 6 0 0 0-6 8L5 22l5 5 9-9a6 6 0 0 0 8-6l-5 3-4-4 2-6Z"/></svg>`;
 return `<svg class="brand-svg support" viewBox="0 0 32 32"><rect x="5" y="6" width="22" height="15" rx="2"/><path d="M11 26h10M16 21v5"/></svg>`;
}
async function copyText(value){
 try{
   if(navigator.clipboard && window.isSecureContext){await navigator.clipboard.writeText(value);return true;}
 }catch(e){}
 try{
   const ta=document.createElement('textarea');ta.value=value;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.opacity='0';
   document.body.appendChild(ta);ta.select();ta.setSelectionRange(0,value.length);const ok=document.execCommand('copy');ta.remove();return ok;
 }catch(e){return false}
}
