function resourceHref(resource){
 const r=typeof resource==='number'?DATA.resources[resource]:resource;
 return r?t(r.href):'#';
}
function resourcePreview(resource){
 const r=typeof resource==='number'?DATA.resources[resource]:resource;
 if(!r)return '';
 const href=resourceHref(r);
 if(href==='#'){
   return `<div class="resource-coming-soon-preview"><img src="${t(r.image)}" alt="${esc(t(r.title))}"></div>`;
 }
 const first=DATA.resources[0],second=DATA.resources[1];
 const ar=lang==='ar';
 let src=t(r.image),alt=t(r.title);
 if(r===first)src=ar?'assets/ui/guide-card-ar-user.png':'assets/ui/guide-card.png';
 if(r===second)src=ar?'assets/ui/cheats-card-ar-user.png':'assets/ui/cheats-card.png';
 return `<div class="resource-artwork" style="--resource-preview-image:url(${src})"><img class="resource-language-art" src="${src}" alt="${esc(alt)}"></div>`;
}
function renderResources(){
 const live=DATA.resources.map((r,i)=>({r,i})).filter(x=>resourceHref(x.r)!=='#' && t(x.r.download)!=='#');
 const soon=DATA.resources.map((r,i)=>({r,i})).filter(x=>resourceHref(x.r)==='#' || t(x.r.download)==='#');
 const card=({r,i})=>{
   const href=resourceHref(r),download=t(r.download)||'';
   const comingSoon=href==='#' || download==='#';
   const actions=comingSoon
     ? `<div class="resource-coming-soon-badge">${lang==='ar'?'قريبًا':'Coming soon'}</div>`
     : `<div class="resource-actions"><button class="resource-action" type="button" data-open-resource="${i}">${lang==='ar'?'عرض المحتوى':'View content'} →</button><button class="resource-download" type="button" data-download-resource="${i}">${lang==='ar'?'تحميل الملف':'Download file'} ↓</button></div>`;
   return `<article class="resource-card${comingSoon?' resource-coming-soon':''}" data-resource-index="${i}" data-resource="${href}" data-resource-title="${esc(t(r.title))}" ${comingSoon?'aria-disabled="true"':'tabindex="0"'}><div class="image">${resourcePreview(r)}</div><div class="copy"><div class="project-top">${r.tags.map(x=>`<span class="pill">${esc(tagLabel(x))}</span>`).join('')}</div><h3>${esc(t(r.title))}</h3><p>${t(r.desc)}</p>${actions}</div></article>`;
 };
 $('resourceGrid').innerHTML=`<div class="resource-live-grid">${live.map(card).join('')}</div><div class="resource-soon-grid">${soon.map(card).join('')}</div>`;
 document.querySelectorAll('.resource-card:not(.resource-coming-soon)').forEach(cardEl=>{
   const r=DATA.resources[Number(cardEl.dataset.resourceIndex)];
   const open=()=>openDocViewer(resourceHref(r),t(r.title),false);
   cardEl.onclick=(e)=>{if(e.target.closest('button,a'))return;open();};
   cardEl.onkeydown=(e)=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button,a')){e.preventDefault();open();}};
 });
 document.querySelectorAll('[data-open-resource]').forEach(btn=>btn.onclick=(e)=>{e.stopPropagation();const r=DATA.resources[Number(btn.dataset.openResource)];openDocViewer(resourceHref(r),t(r.title),false);});
 document.querySelectorAll('[data-download-resource]').forEach(btn=>btn.onclick=(e)=>{e.stopPropagation();handleResourceDownload(DATA.resources[Number(btn.dataset.downloadResource)]);});
}
