function openProject(id){
 const p=DATA.projects.find(x=>x.id===id);if(!p)return;savedScroll=window.scrollY;
 const projectModal=$('projectModal');if(projectModal)projectModal.dataset.projectId=p.id;
 const modalTitle=p.modalTitle?t(p.modalTitle):t(p.title);const modalSubtitle=p.subtitle?t(p.subtitle):'';
 $('modalHead').innerHTML=`<span class="status ${p.status}">${t(p.statusText)}</span><h3 class="modal-title">${esc(modalTitle)}</h3>${modalSubtitle?`<div class="modal-subtitle">${esc(modalSubtitle)}</div>`:''}<p class="modal-intro">${t(p.desc)}</p>`;
 const gallery=$('modalGallery');
 const galleryZoomable=p.id==='penguide-support'||p.id==='soc-network-traffic';
 gallery.classList.toggle('telegram-support-gallery',p.id==='penguide-support');
 gallery.classList.toggle('soc-evidence-gallery',p.id==='soc-network-traffic');
 gallery.innerHTML=p.gallery.map(([src,cap])=>`<figure><img src="${t(src)}" alt=""${galleryZoomable?' class="project-gallery-zoomable" tabindex="0" role="button" aria-label="'+(lang==='ar'?'تكبير الصورة':'Open image with zoom')+'"':''}><figcaption>${t(cap)}</figcaption></figure>`).join('');
 if(galleryZoomable){
   gallery.querySelectorAll('.project-gallery-zoomable').forEach((img,i)=>{
     const openImage=()=>{const item=p.gallery[i];openDocViewer(t(item[0]),t(item[1]),false);};
     img.addEventListener('click',openImage);
     img.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openImage();}});
   });
 }
 $('modalDetails').innerHTML=p.details[lang].map(([h,body])=>`<div class="detail"><h4>${h}</h4>${p.id==='soc-network-traffic'?`<div class="detail-body">${body}</div>`:`<p>${body}</p>`}</div>`).join('');
 const viewHref=p.link?t(p.link):'';
 const downloadHref=p.download?t(p.download):'';
 const labHref=p.labLink?t(p.labLink):'';
 const downloadLabHref=p.downloadLab||'';
 const viewLabel=p.docLabel?t(p.docLabel):(lang==='ar'?'استعراض ملف المشروع':'View project PDF');
 const downloadLabel=p.downloadLabel?t(p.downloadLabel):(lang==='ar'?'تحميل الملف':'Download file');
 const labLabel=lang==='ar'?'عرض المختبر الافتراضي':'View virtual lab';
 const downloadLabLabel=lang==='ar'?'تحميل المختبر الافتراضي':'Download virtual lab';
 $('modalLinks').innerHTML=`${viewHref?`<button class="gold-button" type="button" id="projectDocBtn">${viewLabel} ↗</button>`:''}${downloadHref?`<button class="outline-button" type="button" id="projectDownloadBtn">${downloadLabel} ↓</button>`:''}${labHref?`<button class="outline-button virtual-lab-link" type="button" id="projectLabBtn">${labLabel} ↗</button>`:''}${downloadLabHref?`<button class="outline-button" type="button" id="projectLabDownloadBtn">${downloadLabLabel} ↓</button>`:''}`;
 if(viewHref){const b=$('projectDocBtn');if(b)b.onclick=()=>openDocViewer(viewHref,t(p.title),false);}
 if(downloadHref){const b=$('projectDownloadBtn');if(b)b.onclick=()=>{
   if(p.id==='penguide-support') forceEmbeddedDownload(TELEGRAM_DOC_DOWNLOADS[lang],downloadHref);
   else forceFileDownload(downloadHref,downloadHref.split('/').pop());
 };}
 if(labHref){const b=$('projectLabBtn');if(b)b.onclick=()=>openDocViewer(labHref,lang==='ar'?'المختبر الافتراضي — PenGuide':'Virtual Lab — PenGuide',false);}
 if(downloadLabHref){const b=$('projectLabDownloadBtn');if(b)b.onclick=()=>showLabDownloadWarning(downloadLabHref);}
 const m=$('projectModal');m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';
 requestAnimationFrame(()=>document.querySelector('.modal-panel').scrollTop=0);
}
function closeProject(){const m=$('projectModal');m.classList.remove('open');m.setAttribute('aria-hidden','true');delete m.dataset.projectId;$('modalGallery')?.classList.remove('telegram-support-gallery','soc-evidence-gallery');document.body.style.overflow='';window.scrollTo({top:savedScroll,behavior:'instant'})}
function normalizeViewerSrc(src){
 const clean=String(src||'');
 if(/Abdullah_AlMsan_CV\.pdf(?:$|[?#])/i.test(clean)) return 'resources/pdf-viewer.html?doc=cv';
 if(/\.(?:png|jpe?g|webp)(?:$|[?#])/i.test(clean)) return `resources/image-viewer.html?src=${encodeURIComponent(clean)}`;
 return clean;
}
function viewerLangSrc(src){
 const s=String(src||'');
 // When the portfolio is opened via file://, an iframe cannot reliably read parent.document.
 // Pass the selected portfolio language explicitly to the two localized document viewers.
 if(!/(?:certificates\.html|recommendation-(?:alameen|aldossary)\.html|pdf-viewer\.html)/i.test(s)) return s;
 const sep=s.includes('?')?'&':'?';
 return `${s}${sep}lang=${encodeURIComponent(lang==='ar'?'ar':'en')}`;
}
function viewerZoomProfile(src){
 const s=String(src||'');
 if(/certificates\.html/i.test(s))return .78;
 if(/mobile-device-inspection-guide/i.test(s))return .76;
 if(/library(?:-en)?\.html/i.test(s))return .82;
 if(/virtual-lab(?:-en)?\.html/i.test(s))return .88;
 return .90;
}
function viewerUsesOuterZoom(src){
 const s=String(src||'');
 return /(?:certificates\.html|mobile-device-inspection-guide|library(?:-en)?\.html|virtual-lab(?:-en)?\.html)/i.test(s);
}
function openDocViewer(src,title,downloadable=false){
 const m=$('docModal'),f=$('docViewerFrame'),h=$('docViewerTitle');if(!m||!f)return;
 const initial=viewerZoomProfile(src);
 h.textContent=title||'';
 m.dataset.viewerSrc=String(src||'');
 window.__docDefaultZoom=initial;window.__docZoom=initial;
 const zl=$('docZoomLabel');if(zl)zl.textContent=Math.round(initial*100)+'%';
 const zt=$('docZoomTools');if(zt)zt.hidden=!viewerUsesOuterZoom(src);
 f.style.transform='';f.style.width='100%';f.style.height='calc(100% - 60px)';
 f.src=viewerLangSrc(normalizeViewerSrc(src));
 m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';
 requestAnimationFrame(()=>{const panel=m.querySelector('.doc-panel');if(panel)panel.scrollTop=0;window.__refreshViewerScroll?.();});
}
function closeDocViewer(){
 const m=$('docModal'),f=$('docViewerFrame');if(!m)return;m.classList.remove('open');m.setAttribute('aria-hidden','true');
 if(f){f.src='about:blank';f.style.transform='';f.style.transformOrigin='';f.style.width='100%';f.style.height='calc(100% - 60px)';}
 if(!$('projectModal').classList.contains('open') && !document.getElementById('resumeModal')?.classList.contains('open')) document.body.style.overflow='';
}
window.openDocViewer=openDocViewer;
const closeDoc=$('closeDocModal');if(closeDoc)closeDoc.onclick=closeDocViewer;
const dm=$('docModal');if(dm)dm.onclick=e=>{if(e.target===dm)closeDocViewer()};
function applyDocZoom(){
 const f=$('docViewerFrame'),label=$('docZoomLabel'),modal=$('docModal');if(!f||!modal)return;
 const z=Math.max(.50,Math.min(1.55,Number(window.__docZoom)||1));window.__docZoom=z;
 if(label)label.textContent=Math.round(z*100)+'%';
 if(!viewerUsesOuterZoom(modal.dataset.viewerSrc||'')){window.__refreshViewerScroll?.();return;}
 const panel=modal.querySelector('.doc-panel'),head=modal.querySelector('.doc-viewer-head');if(!panel||!head)return;
 const vh=Math.max(240,panel.clientHeight-head.offsetHeight);
 // Keep the iframe at the viewer's full logical width and scale from its center.
 // This makes 76%, 88%, etc. shrink symmetrically instead of drifting left/right.
 f.style.transformOrigin='top center';
 f.style.transform=`scale(${z})`;
 f.style.width='100%';
 // Compensate only the height so the scaled frame still fills the visible viewer vertically.
 f.style.height=`${vh/z}px`;
 try{f.contentWindow?.dispatchEvent(new Event('resize'));}catch(_){ }
 window.__refreshViewerScroll?.();
}
const dzIn=$('docZoomIn'),dzOut=$('docZoomOut'),dzReset=$('docZoomReset'),dzFrame=$('docViewerFrame');
if(dzIn)dzIn.onclick=()=>{window.__docZoom=Math.min(1.55,Math.round(((window.__docZoom||1)+.12)*100)/100);applyDocZoom()};
if(dzOut)dzOut.onclick=()=>{window.__docZoom=Math.max(.50,Math.round(((window.__docZoom||1)-.12)*100)/100);applyDocZoom()};
if(dzReset)dzReset.onclick=()=>{window.__docZoom=window.__docDefaultZoom||1;applyDocZoom()};
if(dzFrame)dzFrame.addEventListener('load',()=>setTimeout(applyDocZoom,80));
window.addEventListener('resize',()=>{if($('docModal')?.classList.contains('open')&&viewerUsesOuterZoom($('docModal').dataset.viewerSrc||''))applyDocZoom();},{passive:true});
const certBtn=$('certButton');if(certBtn)certBtn.onclick=()=>openDocViewer('certificates.html',lang==='ar'?'الشهادات والدورات التدريبية':'Certificates & Training',false);
document.addEventListener('click',e=>{if(!e.target.closest('.action-wrap'))closeAllMenus();});
